  ('1e32f8ca-b766-5bef-9d2f-c729d550e71c', null, (select id from public.skills where slug = 'read-g11-authors-purpose'), null, 'medium',
   $q$What is the effect of the short sentences "I was not embarrassed. I was delighted."?$q$, $q$[{"text":"They show that he is still unsure how he feels about the concert and needs time to decide.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"They flatly overturn the critic's key word, signaling confident disagreement before he gives his reasons.","is_correct":true},{"text":"They summarize the critic's letter so that readers who missed it understand the complaint.","is_correct":false,"misconception_token":"confuses-speaker"},{"text":"They suggest that he was the only person at the concert who enjoyed the young musicians.","is_correct":false,"misconception_token":"overgeneralization"}]$q$::jsonb, $q$They flatly overturn the critic's key word, signaling confident disagreement before he gives his reasons.$q$, $q$The sentences answer the letter's word "embarrassing" directly and replace it with its opposite, announcing his stance before the explanation. Their bluntness shows certainty, not doubt.$q$, 'draft', '1370c012-d480-57aa-95d6-66a089871fae')
